  std::atomic_bool motion_lock_planar{};
  // Which reference bone table interprets a VMD. Off = the bundled 初音ミク PMD (the model the
  // user plays in MMD, so the game reproduces what they see there); on = the Unity MMD-for-Unity
  // plugin's own reference (Kinsama式初音ミクV4C). A motion authored against one rig reads
  // differently on the other -- resting arms differ by ~35 deg and the hips' travel around the
  // waist by up to 21 cm -- so this is a per-motion choice, not a global "better" one.
  // 0 = bundled Miku PMX, 1 = Unity Miku V4C, 2 = Endfield Standard MMD / A-pose.
  std::atomic<int> motion_reference_mode{1};
  // Conversion-time source IK mode: 0 follow VMD switches, 1 force on, 2 force off.
  std::atomic<int> motion_ik_mode{0};
  std::mutex motion_mapping_mutex;
  std::map<std::string, std::string> manual_motion_mappings;
  std::vector<better_pose::mmd2bip::ManualParentMapping>
      manual_motion_parents;
  std::vector<better_pose::mmd2bip::ManualFingerControl>
      manual_motion_finger_controls;
  std::vector<better_pose::mmd2bip::ManualArmIkControl>
      manual_motion_arm_ik_controls;
  std::set<std::string> ignored_motion_tracks;
  std::string motion_mapping_source;                 // render thread only
  std::array<char, 128> motion_mapping_filter{};      // render thread only
  bool motion_mapping_ui_enabled{};                  // render thread only
  bool motion_mapping_parent_mode{};                 // render thread only
  bool motion_mapping_control_mode{};                // render thread only
  bool motion_mapping_parent_rotation{true};         // render thread only
  bool motion_mapping_parent_position{};             // render thread only
  bool motion_mapping_anchor_picker{};               // render thread only
  std::string motion_mapping_anchor;                 // render thread only
  std::atomic<int> motion_mapping_control_kind{};
  std::atomic<int> motion_mapping_control_side{};
  std::atomic<int> motion_mapping_control_finger{-1};
  std::atomic<int> motion_mapping_control_axis{};
  std::atomic<float> motion_mapping_control_gain{1.0F};
  std::atomic_bool motion_mapping_control_paired{true};
  std::atomic_bool motion_mapping_arm_follow_wrist{};
  std::atomic<float> motion_mapping_arm_gain{1.0F};
  std::atomic<float> motion_mapping_arm_max_bend{150.0F};
  // Live configuration preview. This only affects the currently displayed pose and is never
  // serialized into the motion document.
  std::atomic_bool motion_finger_preview_enabled{};
  std::atomic<float> motion_finger_preview_amount{0.65F};
  std::atomic<int> motion_finger_preview_active_bones{};
  std::atomic_bool motion_arm_preview_enabled{};
  std::atomic<float> motion_arm_preview_amount{0.35F};
  std::atomic<int> motion_arm_preview_active_sides{};
  // Game-thread ownership for VMD whole-model visibility. Failed components stay in the map
  // until they become queryable again, so unload/character changes can finish restoration.
  std::uintptr_t motion_visibility_owner{};
  std::map<std::uintptr_t, bool> motion_visibility_original;
  std::map<std::uintptr_t, bool> motion_visibility_last;
  std::atomic_bool motion_visibility_restore_requested{};
  // Skeleton-independent VMD inspection. Guarded by the mutex because the file action
  // writes it on the scheduler thread while the panel reads it on the render thread.
  std::mutex motion_inspection_mutex;
  std::optional<better_pose::mmd2bip::VmdCompatibilityReport> motion_inspection;
  std::string motion_inspection_path;
  // Camera VMD (a separate file from the motion): loaded on the worker, sampled on the render
  // thread, so the track itself is guarded and only the flags are atomic.
  std::mutex camera_mutex;
  CameraTrack camera;
  std::atomic_bool camera_loaded{};
  std::atomic_bool camera_enabled{};
  std::string camera_file;
  // Follow mode: ignore whatever camera file is loaded and simply keep the character's own
  // displacement in the middle of the frame, from a world direction anchored on the first driven
  // frame. Distance is how far back along that direction the camera sits, height how far above the
  // character's feet; the aim is the character's own chest. Both are centimetres.
  std::atomic_bool camera_follow{};
  // Pose camera: a mouse-only orbit camera for editing, driven through the
  // same view-point hook as the follow camera. Draw posts mouse motion into
  // the orbit (orbit_mutex); the detour turns it into the view each frame.
  std::atomic_bool orbit_enabled{};
  std::atomic_bool orbit_initialized{};
  std::atomic_bool orbit_focus_requested{};
  std::mutex orbit_mutex;
  better_pose::orbit::Orbit orbit;
  std::array<double, 3> orbit_focus_target{};
  std::atomic<double> orbit_focal_pixels{};  // measured from the AHUD projection
  // Pose camera lens: horizontal field of view in degrees (the engine's
  // convention), 0 = leave the game's own. `orbit_game_fov` is the game's value
  // read when the pose camera took over, for the slider's starting point and
  // for handing the lens back when it is switched off.
  std::atomic<float> orbit_fov{};
  std::atomic<float> orbit_game_fov{};
  std::atomic_bool orbit_fov_restore{};
  // Keyframe animation (keyframe_track.hpp): the user's own timeline of poses,
  // expressions and pose-camera shots. The track and the panel-facing copies
  // are guarded by keyframe_mutex; the game thread owns the playhead, samples
  // the track and writes the result into the same state the joint page,
  // expression page and pose camera edit, so everything downstream (pose write,
  // morph write, camera hook) is unchanged. A loaded MMD motion wins over it.
  std::mutex keyframe_mutex;
  better_pose::keyframes::Track keyframe_track;
  std::string keyframe_status;          // guarded by keyframe_mutex
  std::wstring keyframe_import_path;    // guarded by keyframe_mutex
  std::array<char, 128> keyframe_export_name{};
  // Requests from the panel, consumed on the game thread.
  //   1 key the current state at the playhead, 2 delete the selected key,
  //   3 move the selected key to the playhead, 4 clear, 5 export, 6 import,
  //   7 set the selected key's ease (keyframe_ease_request), 8 jump to the
  //   selected key (playhead to its frame).
  std::atomic<int> keyframe_request{};
  std::atomic<double> keyframe_move_frame{};
  std::atomic<int> keyframe_ease_request{};
  std::atomic<std::int32_t> keyframe_selected{-1};
  // What a new key records. Pose is on by default; expression and camera only
  // when asked for, so a pose-only animation does not take the face or the
  // camera over from the game.
  std::atomic_bool keyframe_record_pose{true};
  std::atomic_bool keyframe_record_expression{};
  std::atomic_bool keyframe_record_camera{};
  std::atomic_bool keyframe_auto_record{};
  // Playhead in frames (30 per second). seek < 0 means none.
  std::atomic<double> keyframe_frame{};
  std::atomic<double> keyframe_seek{-1.0};
  std::atomic_bool keyframe_playing{};
  std::atomic_bool keyframe_loop{true};
  std::atomic<float> keyframe_speed{1.0F};
  // Length of the timeline, frames: at least the last key, at least what the
  // user set, so there is room to key beyond the last one.
  std::atomic<std::uint32_t> keyframe_length{150};
  // Set while the track is driving the pose/expression/camera this frame
  // (playing, or the playhead was just moved), so the panel can say so.
  std::atomic_bool keyframe_driving{};
  // Game thread: the playhead the state was last written for, so a paused
  // timeline does not keep overwriting the user's edits every frame.
  double keyframe_applied_frame{-1.0};
  std::uint64_t keyframe_applied_revision{};
  std::uint64_t keyframe_revision{};  // bumped on every track change (guarded)
  double keyframe_auto_last_frame{-1.0};
  better_pose::keyframes::TrackState keyframe_auto_baseline;
  bool keyframe_auto_baseline_valid{};
  better_pose::keyframes::TrackState keyframe_auto_user_state;
  bool keyframe_auto_user_state_valid{};
  // Morphs the track drove last time it wrote, so they are handed back to the
  // game when a later sample no longer drives them. Game thread only.
  std::vector<std::string> keyframe_driven_morphs;
  // Undo/redo of the track (adding, moving, deleting keys). Game thread.

  // On-screen timeline (AHUD canvas). The game thread draws it and publishes
  // the layout; the render thread uses that layout for picking and posts
  // seek/key-move requests back through the existing atomics.
  std::atomic_bool keyframe_overlay_enabled{};
  // A display projection over the same track: one editing row becomes the
